// 資料「slide-deck U10 確認: リトライと指数バックオフ」の資料ごとのスクリプト。
// 構成案 outline.md のキーごとの図を、部品の関数だけで作る。題名・一言・発表者ノートは構成案から読む。
// 図は、題名の下 (y が 1.2 インチ) から、一言の上 (y が 4.6 インチ) までに配置する。

import type { DeckScript, Theme } from "slide-deck";

const theme: Theme = {
  name: "Retry",
  fonts: { heading: "Noto Sans JP", body: "Noto Sans JP" },
  colors: {
    dk1: "1F2933",
    lt1: "FFFFFF",
    dk2: "52606D",
    lt2: "F2F4F7",
    hlink: "1F5FA8",
    folHlink: "6B4F9E",
  },
  accents: {
    accent1: { color: "1F5FA8", meaning: "クライアント" },
    accent2: { color: "3D4F7C", meaning: "API のサーバ" },
    accent3: { color: "0F8B8D", meaning: "待機時間" },
    accent4: { color: "2F9E44", meaning: "リトライが要る・分散している" },
    accent5: { color: "D9480F", meaning: "失敗・リトライが要らない・集中している" },
    accent6: { color: "E8A200", meaning: "上限" },
  },
};

const deck: DeckScript = (p) => {
  // リトライが要る失敗と要らない失敗。2 枚の大きなカードに、見出しと箇条書きを書く
  const failures = p.slide("failures");
  p.card(failures, 0.5, 1.3, 4.3, 3.2);
  p.card(failures, 5.2, 1.3, 4.3, 3.2);
  p.text(failures, [{ text: "リトライが要る失敗", bold: true, color: "accent4" }], 0.8, 1.5, 3.7, 0.45, { fontSize: 18 });
  p.text(failures, [{ text: "リトライが要らない失敗", bold: true, color: "accent5" }], 5.5, 1.5, 3.7, 0.45, { fontSize: 18 });
  p.text(
    failures,
    p.bullets(["503 Service Unavailable", "429 Too Many Requests", "接続のタイムアウト"]),
    0.8,
    2.15,
    3.7,
    1.6,
    { psa: 6 },
  );
  p.text(failures, p.bullets(["400 Bad Request", "404 Not Found", "認証の誤り"]), 5.5, 2.15, 3.7, 1.6, { psa: 6 });

  // 固定の間隔のリトライ。行きの矢印 (左から右) と、失敗を返す破線の矢印 (右から左) を描く
  const fixed = p.slide("fixed");
  const clientYs = [1.35, 2.0, 2.65];
  const names = ["A", "B", "C"];
  clientYs.forEach((y, i) => {
    p.box(fixed, 0.5, y, 1.8, 0.55, `クライアント ${names[i] ?? ""}`, {
      shape: "ellipse",
      fill: "accent1",
      color: "lt1",
      fontSize: 12,
    });
    p.arrow(fixed, 2.3, y + 0.19, 7.4, y + 0.19, { color: "accent1" });
    p.arrow(fixed, 7.4, y + 0.36, 2.3, y + 0.36, { color: "accent5", dash: true });
  });
  p.box(fixed, 7.4, 1.35, 1.9, 1.85, "API の\nサーバ", { shape: "can", fill: "accent2", color: "lt1", bold: true });
  p.arrow(fixed, 0.5, 3.6, 9.5, 3.6, { noHead: true, color: "dk2" });
  [2.5, 5.0, 7.5].forEach((x, i) => {
    p.box(fixed, x - 0.4, 3.4, 0.8, 0.4, "3 件", { shape: "ellipse", fill: "accent5", color: "lt1", fontSize: 11 });
    p.text(fixed, `${String(i + 1)} 秒`, x - 0.4, 3.82, 0.8, 0.3, { fontSize: 11, align: "center", color: "dk2" });
  });
  p.text(
    fixed,
    "事例: ある決済の API では、固定 1 秒の間隔で 5 回までリトライし、障害の間の要求が平常時の 3 倍になった",
    0.5,
    4.12,
    9.0,
    0.42,
    { fontSize: 11, color: "dk2" },
  );

  // 指数バックオフ。五角形の矢印と山形で回ごとの待機時間を示し、下の棒から上へ戻る矢印 (下から上) を描く
  const backoff = p.slide("backoff");
  const waits = [1, 2, 4, 8];
  waits.forEach((w, i) => {
    const x = 0.5 + i * 2.25;
    p.box(
      backoff,
      x,
      1.35,
      2.3,
      0.85,
      [
        { text: `${String(i + 1)} 回目`, bold: true, breakLine: true },
        { text: `待機 ${String(w)} 秒` },
      ],
      { shape: i === 0 ? "homePlate" : "chevron", fill: "accent3", color: "lt1", fontSize: 13 },
    );
    p.box(backoff, 0.5, 2.5 + i * 0.36, w * 0.5, 0.28, "", { shape: "rect", fill: "accent3" });
    p.text(backoff, `${String(w)} 秒`, 0.6 + w * 0.5, 2.48 + i * 0.36, 0.8, 0.32, { fontSize: 11, color: "dk2" });
  });
  p.arrow(backoff, 5.4, 3.72, 8.15, 3.72, { noHead: true, color: "dk2", dash: true });
  p.arrow(backoff, 8.15, 3.72, 8.15, 2.25, { color: "dk2", dash: true });
  p.text(backoff, "同じ時点に失敗したクライアントは、同じ待機時間でリトライする", 0.5, 4.1, 9.0, 0.4, {
    fontSize: 12,
    color: "dk2",
  });

  // ジッタ。上下 2 段の時間の軸に、要求を小さな円で描く
  const jitter = p.slide("jitter");
  p.box(jitter, 0.5, 1.55, 1.6, 0.6, "ジッタなし", { fill: "accent5", color: "lt1", bold: true });
  p.box(jitter, 0.5, 3.0, 1.6, 0.6, "ジッタあり", { fill: "accent4", color: "lt1", bold: true });
  const axisX = (t: number): number => 2.5 + t * 1.6;
  p.arrow(jitter, 2.4, 1.85, 9.5, 1.85, { noHead: true, color: "dk2" });
  p.arrow(jitter, 2.4, 3.3, 9.5, 3.3, { noHead: true, color: "dk2" });
  [1, 2, 4].forEach((t) => {
    [-0.22, -0.05, 0.12].forEach((dy) => {
      p.box(jitter, axisX(t) - 0.09, 1.76 + dy, 0.18, 0.18, "", { shape: "ellipse", fill: "accent5" });
    });
    p.text(jitter, `${String(t)} 秒`, axisX(t) - 0.4, 2.05, 0.8, 0.3, { fontSize: 11, align: "center", color: "dk2" });
    p.text(jitter, `${String(t)} 秒`, axisX(t) - 0.4, 3.5, 0.8, 0.3, { fontSize: 11, align: "center", color: "dk2" });
  });
  [0.3, 0.75, 1.2, 1.55, 2.1, 2.6, 3.05, 3.5, 4.1].forEach((t) => {
    p.box(jitter, axisX(t) - 0.09, 3.21, 0.18, 0.18, "", { shape: "ellipse", fill: "accent4" });
  });

  // 待機時間の上限と打ち切り。縦の棒を上限の破線で切り、打ち切りの箱を右に配置する
  const cap = p.slide("cap");
  const base = 4.2;
  const unit = 0.15;
  const capLine = base - 10 * unit;
  [1, 2, 4, 8, 16].forEach((w, i) => {
    const x = 0.8 + i * 0.85;
    const h = w * unit;
    if (base - h < capLine) {
      p.box(cap, x, base - h, 0.5, capLine - (base - h), "", { shape: "rect", fill: "accent3", tr: 70 });
      p.box(cap, x, capLine, 0.5, base - capLine, "", { shape: "rect", fill: "accent3" });
    } else {
      p.box(cap, x, base - h, 0.5, h, "", { shape: "rect", fill: "accent3" });
    }
    p.text(cap, `${String(w)} 秒`, x - 0.15, base + 0.03, 0.8, 0.3, { fontSize: 11, align: "center", color: "dk2" });
  });
  p.arrow(cap, 0.6, capLine, 4.9, capLine, { noHead: true, color: "accent6", dash: true, width: 2 });
  p.text(cap, [{ text: "上限 10 秒", bold: true, color: "accent6" }], 4.95, capLine - 0.2, 1.2, 0.4, { fontSize: 12 });
  p.box(
    cap,
    6.3,
    1.9,
    3.2,
    1.8,
    [
      { text: "5 回で打ち切り", bold: true, fontSize: 18, breakLine: true },
      { text: "呼び出し元に失敗を返す" },
    ],
    { fill: "lt2", line: "accent5", lineW: 1.5 },
  );

  // 参考にした資料。題名をリンクにし、下に内容を 1 行で書く
  const refs = p.slide("refs");
  p.badge(refs, 1, 0.5, 1.6, 0.32, { fill: "accent1" });
  p.badge(refs, 2, 0.5, 2.9, 0.32, { fill: "accent1" });
  p.text(
    refs,
    [{ text: "Marc Brooker「Exponential Backoff and Jitter」", link: "https://aws.amazon.com/blogs/architecture/exponential-backoff-and-jitter/" }],
    1.0,
    1.52,
    8.5,
    0.48,
    { fontSize: 16 },
  );
  p.text(refs, "AWS Architecture Blog、2015 年。ジッタの種類と、その比較", 1.0, 2.0, 8.5, 0.4, { fontSize: 12, color: "dk2" });
  p.text(
    refs,
    [{ text: "「Mastering Exponential Backoff in Distributed Systems」", link: "https://betterstack.com/community/guides/monitoring/exponential-backoff/" }],
    1.0,
    2.82,
    8.5,
    0.48,
    { fontSize: 16 },
  );
  p.text(refs, "Better Stack Community。リトライする失敗としない失敗", 1.0, 3.3, 8.5, 0.4, { fontSize: 12, color: "dk2" });

